"""Native browser client for the local screening service."""

HTML = r'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SEC 기업 스크리닝</title><link rel="icon" href="/app.css"><link rel="stylesheet" href="/app.css"></head>
<body><a class="skip" href="#results">결과로 건너뛰기</a>
<nav class="task-nav" aria-label="작업 탐색"><a href="#criteria-title" class="brand" aria-label="SEC 스크리닝 홈"><span>SEC</span><b>XBRL</b></a><a href="#criteria-title" class="active"><span>01</span>조건</a><a href="#results"><span>02</span>결과</a><a href="#directory-title"><span>03</span>회사</a><a href="#history-title"><span>04</span>이력</a></nav>
<header><div><span class="eyebrow">SEC XBRL · PREPARED ANALYTICS</span><h1>기업 스크리닝 작업대</h1></div>
<div id="save-state" role="status" aria-live="polite">저장 대기</div></header>
<main>
<section class="ledger" aria-label="실행 문맥">
  <dl><div><dt>재무 기준일</dt><dd id="asof">—</dd></div><div><dt>기간</dt><dd id="period-context">—</dd></div>
  <div><dt>Universe</dt><dd id="universe-context">—</dd></div><div><dt>저장 조건</dt><dd id="screen-context">새 조건</dd></div>
  <div><dt>실행</dt><dd id="run-context">아직 실행 안 함</dd></div><div><dt>검토 상태</dt><dd id="review-context">준비됨</dd></div></dl>
  <details><summary>자료 출처·버전</summary><pre id="provenance">—</pre></details>
</section>
<section class="criteria" aria-labelledby="criteria-title"><div class="section-head"><div><span class="index">01</span><h2 id="criteria-title">조건 정의</h2></div>
<div class="button-row"><button id="toggle-criteria" type="button" class="quiet" aria-expanded="true" aria-controls="criteria-form">조건 접기</button><button id="new-screen" type="button" class="quiet">새 조건</button><button id="save-screen" type="button">새 조건 버전 저장</button></div></div>
<form id="criteria-form">
 <label>다음 실행 데이터셋<select id="dataset" required></select></label><label>저장 조건 다시 열기<select id="saved-screen"><option value="">새 조건</option></select></label><label>조건 이름<input id="screen-name" required maxlength="80" placeholder="예: FY2025 현금흐름 검토"></label>
 <label>Universe<select id="universe-mode"><option value="ALL_PREPARED">준비된 전체 회사</option><option value="SIC">SEC SIC로 좁히기</option><option value="CIKS">CIK 직접 선택</option></select></label>
 <label id="universe-values-label" hidden>Universe 값<input id="universe-values" placeholder="쉼표로 구분"></label>
 <label>기간 정책<select id="period-mode"><option value="FIXED_FISCAL_YEAR">고정 FY</option><option value="LATEST_COMPLETE_ANNUAL">최신 완료 FY</option></select></label>
 <label id="fiscal-year-label">FY<input id="fiscal-year" type="number" min="1900" max="2200" value="2025"></label>
 <label id="offset-label" hidden>이전 연도 offset<input id="period-offset" type="number" min="0" max="20" value="0"></label>
 <fieldset><legend>AND 조건</legend><div id="predicates"></div><button id="add-predicate" class="quiet" type="button">+ 조건 추가</button></fieldset>
 <label>정렬<select id="sort-column"><option value="ticker">티커</option><option value="cik">CIK</option><option value="aggregate">판정</option><option value="metric:revenue">매출 값</option><option value="metric:cfo">영업활동 현금흐름 값</option></select></label>
 <label>방향<select id="sort-direction"><option value="ASC">오름차순</option><option value="DESC">내림차순</option></select></label>
 <fieldset class="columns"><legend>표시 열</legend><label class="inline"><input type="checkbox" name="visible-column" value="company" checked> 회사·CIK</label><label class="inline"><input type="checkbox" name="visible-column" value="sic" checked> SEC SIC</label><label class="inline"><input type="checkbox" name="visible-column" value="aggregate" checked> 판정</label><label class="inline"><input type="checkbox" name="visible-column" value="predicates" checked> 조건별 값</label><label class="inline"><input type="checkbox" name="visible-column" value="decision" checked> 사용자 판단</label></fieldset>
 </form>
 <div id="criteria-error" class="message error" role="alert" hidden></div>
</section>
<section class="workspace"><div class="section-head"><div><span class="index">02</span><h2>전 회사 결과</h2><p id="counts">조건을 저장하고 실행하세요.</p></div>
<div class="button-row"><button id="execute" type="button">실행</button><label class="inline"><input id="show-all" type="checkbox" checked> 전체 상태 표시</label></div></div>
<div class="filters" role="group" aria-label="결과 상태 필터"><button type="button" data-filter="ALL" class="active">전체</button><button type="button" data-filter="PASS">통과</button><button type="button" data-filter="FAIL">미충족</button><button type="button" data-filter="UNDETERMINED">미결정</button><button type="button" data-filter="BLOCK">품질 차단</button></div>
<div class="table-wrap"><table id="results"><thead><tr><th><span class="sr-only">선택</span></th><th data-column="company">회사 / CIK</th><th data-column="sic">SEC SIC</th><th data-column="aggregate">판정</th><th data-column="predicates">조건별 값·이유</th><th data-column="decision">사용자 판단</th></tr></thead><tbody id="result-body"><tr><td colspan="6" class="empty">아직 실행 결과가 없습니다.</td></tr></tbody></table></div>
</section>
<section class="directory"><div class="section-head"><div><span class="index">META</span><h2 id="directory-title">회사·산업 후보 찾기</h2><p>재무 준비 대상과 UNKNOWN_SIC 후보를 함께 조회합니다.</p></div></div><form id="metadata-form"><label>이름·티커·CIK<input id="metadata-query"></label><label>SEC SIC<input id="metadata-sic"></label><label>재무 준비 상태<select id="metadata-prepared"><option value="">전체</option><option value="true">준비됨</option><option value="false">미준비 후보</option></select></label><button type="submit" class="quiet">찾기</button></form><div id="metadata-results" class="metadata-results">조회 전</div><div class="pager"><button id="metadata-prev" type="button" class="quiet">이전 50개</button><span id="metadata-page" aria-live="polite">—</span><button id="metadata-next" type="button" class="quiet">다음 50개</button></div></section>
<section class="history"><div class="section-head"><div><span class="index">03</span><h2 id="history-title">실행과 판단 이력</h2></div>
<div class="button-row"><button id="open-run" type="button" class="quiet">선택 실행 열기</button><button id="export-full-csv" type="button" class="quiet">전체 CSV</button><button id="export-full-xlsx" type="button" class="quiet">전체 XLSX</button><button id="export-selected-csv" type="button" class="quiet">선택 CSV</button><button id="export-selected-xlsx" type="button" class="quiet">선택 XLSX</button></div></div>
<div class="compare"><label>옛 실행<select id="old-run"></select></label><label>새 실행<select id="new-run"></select></label><button id="compare-runs" type="button" class="quiet">차이 보기</button></div>
<div id="run-diff" class="diff empty-diff">실행 비교 대기</div><ol id="timeline"></ol></section>
</main>
<aside id="evidence" aria-labelledby="evidence-title" tabindex="-1" hidden><div class="aside-head"><div><span class="index">TRACE</span><h2 id="evidence-title">값과 판단 근거</h2></div><button id="close-evidence" type="button" aria-label="근거 패널 닫기">닫기</button></div>
<div id="evidence-content"></div><section><h3>연간 시계열·SIC 비교</h3><label>근거 지표<select id="evidence-metric"></select></label><label>SIC peer<select id="peer-company"><option value="">peer 선택</option></select></label><button id="compare-peer" type="button" class="quiet">실제 기간 비교</button><div id="peer-comparison"></div></section><section><h3>사용자 판단 기록</h3><label>상태<select id="decision-state"><option value="INTEREST">관심</option><option value="HOLD">보류</option><option value="EXCLUDE">제외</option></select></label><label>근거<textarea id="decision-rationale" rows="3" required></textarea></label><button id="save-decision" type="button">판단 기록 추가</button><p class="muted">판단 메모는 재무 사실이나 스크리닝 판정을 바꾸지 않습니다.</p></section></aside>
<div id="toast" role="status" aria-live="polite"></div><script src="/app.js"></script></body></html>'''

CSS = r'''@font-face{font-family:PreparedKorean;src:local("Malgun Gothic");font-display:swap}
:root{font-family:PreparedKorean,"Malgun Gothic","Noto Sans KR",system-ui,sans-serif;color:#232a2c;background:#f2efe7;font-size:14px;--paper:#f2efe7;--sheet:#fbfaf5;--ink:#232a2c;--slate:#667174;--line:#d7d2c6;--inset:#eeece4;--blue:#225e80;--blue-soft:#e2edf2;--amber:#8b5a12;--amber-soft:#f7ead0;--red:#983d36;--red-soft:#f5dfdc;--green:#32634f;--focus:#1b719d}*{box-sizing:border-box}body{margin:0}.skip{position:fixed;left:12px;top:-60px;background:var(--ink);color:white;padding:10px;z-index:20}.skip:focus{top:12px}header{min-height:76px;padding:16px 28px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);background:var(--sheet);position:sticky;top:0;z-index:3}h1{font-size:24px;line-height:1.1;margin:3px 0;letter-spacing:-.03em}h2{font-size:18px;margin:0;letter-spacing:-.02em}h3{font-size:14px}.eyebrow,.index{font-size:10px;letter-spacing:.13em;color:var(--blue);font-weight:700}.index{display:inline-block;margin-bottom:4px}#save-state{font-size:12px;color:var(--slate)}main{max-width:1600px;margin:auto;padding:16px 24px 48px}.ledger,.criteria,.workspace,.history{background:var(--sheet);border:1px solid var(--line);margin-bottom:12px}.ledger{padding:12px 16px}.ledger dl{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));margin:0}.ledger dl div{padding:6px 12px;border-right:1px solid var(--line)}.ledger dl div:last-child{border:0}dt{font-size:10px;color:var(--slate);text-transform:uppercase}dd{margin:4px 0 0;font-weight:650;font-variant-numeric:tabular-nums}.ledger details{border-top:1px solid var(--line);margin-top:8px;padding-top:8px}summary{cursor:pointer;color:var(--slate)}pre{white-space:pre-wrap;word-break:break-word;font:11px ui-monospace,monospace;background:var(--inset);padding:12px;border:1px solid var(--line)}.section-head{padding:14px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line)}.section-head p{margin:4px 0 0;color:var(--slate);font-size:12px}.button-row{display:flex;flex-wrap:wrap;gap:8px}button,input,select,textarea{font:inherit;color:var(--ink)}button{border:1px solid #1f5874;background:var(--blue);color:white;padding:8px 12px;cursor:pointer}button.quiet,.filters button{background:transparent;color:var(--ink);border-color:var(--line)}button:hover{filter:brightness(.95)}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid var(--focus);outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.45}.criteria form{padding:14px 16px;display:grid;grid-template-columns:repeat(6,minmax(140px,1fr));gap:12px;align-items:end}.criteria label,.compare label,aside label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:650;color:var(--slate)}input,select,textarea{width:100%;border:1px solid #c7c2b7;background:var(--inset);padding:8px;color:var(--ink)}fieldset{grid-column:1/-1;border:1px solid var(--line);padding:10px}legend{font-size:11px;color:var(--slate)}.predicate{display:grid;grid-template-columns:2fr 1fr 2fr auto;gap:8px;margin-bottom:8px}.filters{padding:10px 16px;display:flex;gap:6px;border-bottom:1px solid var(--line)}.filters button{padding:5px 9px;font-size:11px}.filters button.active{background:var(--blue-soft);border-color:var(--blue)}.inline{display:flex;flex-direction:row;align-items:center;gap:7px}.inline input{width:auto}.table-wrap{overflow:auto;max-height:60vh}table{border-collapse:collapse;width:100%;min-width:980px}th{position:sticky;top:0;background:#e9e6dc;color:#495457;text-align:left;font-size:11px;letter-spacing:.02em;z-index:1}th,td{padding:9px 12px;border-bottom:1px solid #e5e1d7;vertical-align:top}tbody tr:hover,tbody tr.selected{background:var(--blue-soft)}td:first-child{width:34px}.company strong{display:block}.company small,.muted{color:var(--slate);font-size:11px}.badge{display:inline-flex;align-items:center;padding:3px 7px;font-size:10px;font-weight:750;border:1px solid currentColor}.pass{color:var(--green)}.fail{color:var(--red)}.undetermined,.review{color:var(--amber)}.pred-list{display:grid;gap:4px}.pred-line{font-variant-numeric:tabular-nums;font-size:12px}.pred-line small{display:block;color:var(--slate)}.empty{text-align:center;color:var(--slate);padding:48px}.history{padding-bottom:14px}.compare{display:flex;align-items:end;gap:8px;padding:12px 16px}.compare label{min-width:220px}.diff{margin:0 16px}.history ol{margin:12px 16px;padding-left:22px}.history li{padding:5px}aside{position:fixed;right:0;top:0;width:min(570px,100vw);height:100vh;z-index:8;background:var(--sheet);border-left:1px solid var(--line);box-shadow:-18px 0 60px #252c2e24;padding:16px;overflow:auto}.aside-head{display:flex;justify-content:space-between;align-items:start;border-bottom:1px solid var(--line);padding-bottom:12px}.trace-grid{display:grid;grid-template-columns:120px 1fr;gap:7px;margin:14px 0}.trace-grid dt,.trace-grid dd{margin:0;padding-bottom:5px;border-bottom:1px solid #e8e4da}.message{margin:0 16px 12px;padding:10px}.error{background:var(--red-soft);color:var(--red);border-left:4px solid var(--red)}#toast{position:fixed;left:50%;bottom:18px;transform:translateX(-50%);background:var(--ink);color:white;padding:9px 14px;opacity:0;pointer-events:none;transition:opacity .15s;z-index:12}#toast.visible{opacity:1}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}[hidden]{display:none!important}@media(max-width:1100px){main{padding:12px}.ledger dl{grid-template-columns:repeat(3,1fr)}.ledger dl div:nth-child(3){border-right:0}.criteria form{grid-template-columns:repeat(3,1fr)}.section-head{align-items:start}.predicate{grid-template-columns:2fr 1fr 2fr auto}header{padding:12px 16px}}'''

CSS += r'''.directory{background:var(--sheet);border:1px solid var(--line);margin-bottom:12px}.criteria label,.compare label,aside label,.directory label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:650;color:var(--slate)}.columns{display:flex;gap:14px;flex-wrap:wrap}.directory form{padding:12px 16px;display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:8px;align-items:end}.metadata-results{padding:12px 16px;color:var(--slate)}.metadata-results ul{columns:3;padding-left:18px}.series-table{min-width:0;font-size:11px}@media(max-width:1100px){.directory form{grid-template-columns:2fr 1fr 1fr auto}.metadata-results ul{columns:2}}'''

CSS += r'''body{padding-left:68px}.task-nav{position:fixed;inset:0 auto 0 0;width:68px;z-index:6;background:var(--ink);display:flex;flex-direction:column}.task-nav a{color:#d9ddda;text-decoration:none;text-align:center;padding:14px 4px;font-size:11px;border-left:3px solid transparent}.task-nav a span{display:block;font:10px ui-monospace,monospace;color:#9ba7a5;margin-bottom:3px}.task-nav a:hover,.task-nav a:focus-visible,.task-nav a.active{background:#30383a;color:#fff;border-left-color:#6fa8c4}.task-nav .brand{height:76px;display:flex;flex-direction:column;justify-content:center;color:#fff;border-bottom:1px solid #ffffff1c}.task-nav .brand span{color:#8fc0d6;font-weight:800}.task-nav .brand b{font-size:11px;letter-spacing:.08em}.criteria:before{content:"UNIVERSE CRITERIA  /  FILTER CRITERIA";display:block;padding:8px 16px;background:#e9e6dc;color:var(--slate);font:700 10px ui-monospace,monospace;letter-spacing:.08em;border-bottom:1px solid var(--line)}.workspace{border-top:3px solid var(--blue)}.company{padding:0!important;border:0!important;text-align:left!important;background:transparent!important;color:var(--ink)!important}.company:hover strong{text-decoration:underline;text-underline-offset:3px}.pager{display:flex;justify-content:flex-end;align-items:center;gap:12px;padding:0 16px 14px}.pager span{color:var(--slate);font-variant-numeric:tabular-nums}.diff{margin:0 16px;padding:12px;background:var(--inset);border:1px solid var(--line)}.empty-diff{color:var(--slate)}.diff-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.diff-summary div{background:var(--sheet);border:1px solid var(--line);padding:10px}.diff-summary strong{display:block;margin-bottom:4px}.diff details{margin-top:10px}.timeline-meta{color:var(--slate);font-size:11px}.loading{color:var(--blue)}.technical{font-family:ui-monospace,monospace;font-size:11px}.reason{margin-top:3px}.reason summary{font-size:11px}.reason code{display:block;margin-top:4px;color:var(--slate);white-space:normal}.series-table td{font-variant-numeric:tabular-nums}.history ol{display:grid;gap:6px;list-style:none;padding:0;margin:12px 16px}.history li{border-left:3px solid var(--line);background:var(--inset);padding:8px 10px}.history li.decision{border-left-color:var(--amber)}@media(max-width:1100px){body{padding-left:52px}.task-nav{width:52px}.task-nav .brand{height:68px}.task-nav a{font-size:10px;padding:12px 2px}main{padding:12px 10px}.ledger dl{grid-template-columns:repeat(3,minmax(0,1fr))}.criteria form{grid-template-columns:repeat(3,minmax(0,1fr))}.section-head{flex-wrap:wrap}.button-row{gap:4px}.button-row button{padding:7px 8px}.compare{flex-wrap:wrap}.compare label{min-width:180px;flex:1}.diff-summary{grid-template-columns:1fr}.metadata-results ul{columns:2}}'''

CSS += r'''.criteria.compact:before{content:"SAVED CRITERIA · COMPACT"}.criteria.compact #criteria-form,.criteria.compact #criteria-error{display:none}.criteria.compact .section-head{border-bottom:0}.exact-value{font:10px ui-monospace,monospace;color:var(--slate)}.state-label{font-weight:750}.timeline-primary{display:flex;justify-content:space-between;gap:12px}.timeline-primary time{color:var(--slate);font-size:11px;font-weight:400}.timeline-technical{margin-top:6px}.timeline-technical pre{margin:6px 0 0}.pred-line>small{margin-top:2px}.pred-line details{max-width:620px}'''

CSS += r'''body{padding-left:68px}.task-nav{position:fixed;inset:0 auto 0 0;width:68px;z-index:6;background:var(--ink);display:flex;flex-direction:column}.task-nav a{color:#d9ddda;text-decoration:none;text-align:center;padding:14px 4px;font-size:11px;border-left:3px solid transparent}.task-nav a span{display:block;font:10px ui-monospace,monospace;color:#9ba7a5;margin-bottom:3px}.task-nav a:hover,.task-nav a:focus-visible,.task-nav a.active{background:#30383a;color:#fff;border-left-color:#6fa8c4}.task-nav .brand{height:76px;display:flex;flex-direction:column;justify-content:center;color:#fff;border-bottom:1px solid #ffffff1c}.task-nav .brand span{color:#8fc0d6;font-weight:800}.task-nav .brand b{font-size:11px;letter-spacing:.08em}.criteria:before{content:"UNIVERSE CRITERIA  /  FILTER CRITERIA";display:block;padding:8px 16px;background:#e9e6dc;color:var(--slate);font:700 10px ui-monospace,monospace;letter-spacing:.08em;border-bottom:1px solid var(--line)}.workspace{border-top:3px solid var(--blue)}.company{padding:0!important;border:0!important;text-align:left!important;background:transparent!important;color:var(--ink)!important}.company:hover strong{text-decoration:underline;text-underline-offset:3px}.pager{display:flex;justify-content:flex-end;align-items:center;gap:12px;padding:0 16px 14px}.pager span{color:var(--slate);font-variant-numeric:tabular-nums}.diff{margin:0 16px;padding:12px;background:var(--inset);border:1px solid var(--line)}.empty-diff{color:var(--slate)}.diff-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.diff-summary div{background:var(--sheet);border:1px solid var(--line);padding:10px}.diff-summary strong{display:block;margin-bottom:4px}.diff details{margin-top:10px}.timeline-meta{color:var(--slate);font-size:11px}.loading{color:var(--blue)}.technical{font-family:ui-monospace,monospace;font-size:11px}.reason{margin-top:3px}.reason summary{font-size:11px}.reason code{display:block;margin-top:4px;color:var(--slate);white-space:normal}.series-table td{font-variant-numeric:tabular-nums}.history ol{display:grid;gap:6px;list-style:none;padding:0;margin:12px 16px}.history li{border-left:3px solid var(--line);background:var(--inset);padding:8px 10px}.history li.decision{border-left-color:var(--amber)}@media(max-width:1100px){body{padding-left:52px}.task-nav{width:52px}.task-nav .brand{height:68px}.task-nav a{font-size:10px;padding:12px 2px}main{padding:12px 10px}.ledger dl{grid-template-columns:repeat(3,minmax(0,1fr))}.criteria form{grid-template-columns:repeat(3,minmax(0,1fr))}.section-head{flex-wrap:wrap}.button-row{gap:4px}.button-row button{padding:7px 8px}.compare{flex-wrap:wrap}.compare label{min-width:180px;flex:1}.diff-summary{grid-template-columns:1fr}.metadata-results ul{columns:2}}'''

JS = r'''const S={screens:[],runs:[],revision:null,run:null,selected:new Set(),activeFilter:"ALL",lastFocus:null};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
async function api(path,options={}){const response=await fetch(path,{headers:{"Content-Type":"application/json"},...options});const body=await response.json().catch(()=>({error:`HTTP ${response.status}`}));if(!response.ok)throw new Error(body.error||"요청 실패");return body}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("visible");setTimeout(()=>el.classList.remove("visible"),1800)}
function fail(error){$("#criteria-error").hidden=false;$("#criteria-error").textContent=error.message||String(error);$("#save-state").textContent="작업 실패 · 저장되지 않음"}
function predicateRow(value={metric_id:"revenue",operator:"GTE",threshold:"0",definition_version:"annual-core-reported-v1"}){const row=document.createElement("div");row.className="predicate";row.innerHTML=`<label>지표<select class="metric"><option value="revenue">매출</option><option value="cfo">영업활동 현금흐름</option><option value="operating_income">영업이익</option><option value="net_income">순이익</option><option value="revenue_growth" disabled>매출 성장률 · ACTUAL_PERIOD_REQUIRED</option><option value="operating_margin" disabled>영업이익률 · ACTUAL_PERIOD_REQUIRED</option></select></label><label>비교<select class="operator"><option>GTE</option><option>GT</option><option>LTE</option><option>LT</option><option>EQ</option></select></label><label>기준값<input class="threshold" inputmode="decimal" required></label><button type="button" class="quiet remove" aria-label="조건 삭제">삭제</button>`;row.querySelector(".metric").value=value.metric_id;row.querySelector(".operator").value=value.operator;row.querySelector(".threshold").value=value.threshold;row.querySelector(".remove").onclick=()=>{if($$(".predicate").length>1)row.remove()};$("#predicates").append(row)}
function revisionContent(){const mode=$("#universe-mode").value, values=$("#universe-values").value.split(",").map(v=>v.trim()).filter(Boolean);const universe=mode==="ALL_PREPARED"?{mode}:mode==="SIC"?{mode,sic_codes:values}:{mode,ciks:values};const period=$("#period-mode").value==="FIXED_FISCAL_YEAR"?{mode:"FIXED_FISCAL_YEAR",fiscal_year:Number($("#fiscal-year").value)}:{mode:"LATEST_COMPLETE_ANNUAL",offset:Number($("#period-offset").value)};return {universe,predicates:$$(".predicate").map(row=>({metric_id:row.querySelector(".metric").value,operator:row.querySelector(".operator").value,threshold:row.querySelector(".threshold").value,definition_version:"annual-core-reported-v1"})),period_policy:period,columns:["ticker","name","sic_code","aggregate","predicates"],sort:{column:$("#sort-column").value,direction:$("#sort-direction").value}}}
async function boot(){const status=await api("/api/status");$("#dataset").innerHTML=status.datasets.map(d=>`<option value="${esc(d.dataset_id)}">${esc(d.dataset_id)} · ${esc(d.fixture_kind)}</option>`).join("");await refreshScreens();await refreshRuns();updateDataset(status.datasets[0]);predicateRow()}
function updateDataset(d){$("#asof").textContent=d.financial_as_of;$("#universe-context").textContent=`${d.counts.companies}개 prepared`;$("#provenance").textContent=JSON.stringify(d,null,2)}
async function refreshScreens(){S.screens=await api("/api/screens");$("#saved-screen").innerHTML='<option value="">새 조건</option>'+S.screens.map(x=>`<option value="${x.revision_id}">${esc(x.name)} · r${x.revision_number}</option>`).join('');renderTimeline()}
async function refreshRuns(){S.runs=await api("/api/runs");const options='<option value="">실행 선택</option>'+S.runs.map(r=>`<option value="${r.run_id}">${r.run_id.slice(-8)} · ${r.fixture_kind}</option>`).join("");$("#old-run").innerHTML=options;$("#new-run").innerHTML=options;renderTimeline()}
async function saveScreen(){$("#criteria-error").hidden=true;$("#save-state").textContent="저장 중…";const content=revisionContent();let result;if(S.revision)result=await api(`/api/screens/${S.revision.screen_id}/revisions`,{method:"POST",body:JSON.stringify({content})});else result=await api("/api/screens",{method:"POST",body:JSON.stringify({name:$("#screen-name").value,content})});S.revision=result;$("#save-state").textContent=`저장됨 · revision ${result.revision_number}`;$("#screen-context").textContent=`${$("#screen-name").value} · r${result.revision_number}`;await refreshScreens();toast("저장 완료")}
function loadScreen(id){const screen=S.screens.find(x=>x.revision_id===id);if(!screen)return;S.revision=screen;$("#screen-name").value=screen.name;const c=screen.content;$("#universe-mode").value=c.universe.mode;$("#universe-values-label").hidden=c.universe.mode==="ALL_PREPARED";$("#universe-values").value=(c.universe.ciks||c.universe.sic_codes||[]).join(',');$("#period-mode").value=c.period_policy.mode;$("#fiscal-year-label").hidden=c.period_policy.mode!=="FIXED_FISCAL_YEAR";$("#offset-label").hidden=c.period_policy.mode==="FIXED_FISCAL_YEAR";if(c.period_policy.fiscal_year)$("#fiscal-year").value=c.period_policy.fiscal_year;$("#period-offset").value=c.period_policy.offset||0;$("#predicates").innerHTML='';c.predicates.forEach(predicateRow);$("#sort-column").value=c.sort.column;$("#sort-direction").value=c.sort.direction;$("#screen-context").textContent=`${screen.name} · r${screen.revision_number}`;$("#save-state").textContent="저장된 revision 열림"}
async function execute(){if(!S.revision)throw new Error("먼저 조건을 저장하세요.");$("#result-body").innerHTML='<tr><td colspan="6" class="empty">실행 중…</td></tr>';const run=await api("/api/runs",{method:"POST",body:JSON.stringify({revision_id:S.revision.revision_id,dataset_id:$("#dataset").value})});S.run=run;S.selected.clear();$("#run-context").textContent=`${run.run_id.slice(-8)} · ${run.fixture_kind}`;$("#period-context").textContent=run.period_policy.mode==="FIXED_FISCAL_YEAR"?`FY${run.period_policy.fiscal_year}`:`최신 FY -${run.period_policy.offset||0}`;$("#counts").textContent=`대상 ${run.counts.target} · PASS ${run.counts.pass} · FAIL ${run.counts.fail} · 미결정 ${run.counts.undetermined} · quality block ${run.counts.quality_block} (중복 subset)`;renderRows();await refreshRuns()}
function openRun(id){const run=S.runs.find(x=>x.run_id===id);if(!run)throw new Error("실행을 선택하세요.");S.run=run;S.selected.clear();$("#run-context").textContent=`${run.run_id.slice(-8)} · ${run.fixture_kind}`;$("#period-context").textContent=run.period_policy.mode==="FIXED_FISCAL_YEAR"?`FY${run.period_policy.fiscal_year}`:`최신 FY -${run.period_policy.offset||0}`;$("#counts").textContent=`대상 ${run.counts.target} · PASS ${run.counts.pass} · FAIL ${run.counts.fail} · 미결정 ${run.counts.undetermined} · quality block ${run.counts.quality_block} (중복 subset)`;renderRows()}
function renderRows(){if(!S.run)return;const rows=S.run.rows.filter(r=>S.activeFilter==="ALL"||(S.activeFilter==="BLOCK"?r.quality_blocking:r.aggregate===S.activeFilter)).filter(r=>$("#show-all").checked||r.aggregate==="PASS");$("#result-body").innerHTML=rows.length?rows.map(row=>`<tr data-cik="${row.cik}" class="${S.selected.has(row.cik)?'selected':''}"><td><input type="checkbox" aria-label="${esc(row.ticker)} 선택" ${S.selected.has(row.cik)?'checked':''}></td><td><button class="quiet company" data-open="${row.cik}"><strong>${esc(row.ticker)} · ${esc(row.name||'이름 미제공')}</strong><small>${row.cik}</small></button></td><td>${esc(row.sic_code||'UNKNOWN_SIC')}<br><small>${esc(row.sic_description||'현재 분류 없음')}</small></td><td><span class="badge ${row.aggregate.toLowerCase()}">${row.aggregate}</span>${row.quality_blocking?'<br><span class="badge fail">QUALITY BLOCK</span>':''}</td><td><div class="pred-list">${row.predicates.map(p=>`<div class="pred-line"><b>${esc(p.metric_id)}</b> ${p.observation&&p.observation.value!==null?esc(p.observation.value):'—'} · ${p.result}<small>${esc(p.reason)}</small></div>`).join('')}</div></td><td>${decisionFor(row.cik)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">0건 · 상태 필터나 조건을 수정하세요.</td></tr>';$$('[data-cik] input').forEach(el=>el.onchange=()=>{const cik=el.closest('tr').dataset.cik;el.checked?S.selected.add(cik):S.selected.delete(cik);renderRows()});$$('[data-open]').forEach(el=>el.onclick=()=>openEvidence(el.dataset.open,el))}
function decisionFor(cik){const events=(S.decisions||[]).filter(e=>e.cik===cik);return events.length?`<span class="badge review">${events.at(-1).state}</span>`:'<span class="muted">기록 없음</span>'}
async function openEvidence(cik,button){S.lastFocus=button;const row=S.run.rows.find(r=>r.cik===cik);const first=row.predicates[0], obs=first.observation||{};const peers=await api(`/api/peers?dataset_id=${encodeURIComponent(S.run.dataset_id)}&cik=${cik}`);$("#evidence-title").textContent=`${row.ticker} 근거`;$("#evidence-content").innerHTML=`<dl class="trace-grid"><dt>CIK</dt><dd>${row.cik}</dd><dt>판정</dt><dd>${row.aggregate}</dd><dt>실제 기간</dt><dd>${esc(obs.period_start||'—')} → ${esc(obs.context_end_date||'—')} <small>(source context end, exclusive)</small></dd><dt>단위</dt><dd>${esc(JSON.stringify(obs.unit||null))}</dd><dt>공시</dt><dd>${esc((obs.source_filings||[]).join(', ')||'—')}</dd><dt>Fact</dt><dd>${esc(obs.source_fact_id||'—')}</dd><dt>Mapping</dt><dd>${esc(obs.mapping_relation||'—')}</dd><dt>Quality</dt><dd>${esc(obs.quality_status===null||obs.quality_status===undefined?'NOT_DECLARED':obs.quality_status)}</dd><dt>SIC peers</dt><dd>${peers.peers.length}개 · ${esc(peers.limitation)}</dd></dl><details><summary>전체 prepared trace</summary><pre>${esc(JSON.stringify(first,null,2))}</pre></details>`;$("#evidence").dataset.cik=cik;$("#evidence").hidden=false;$("#evidence").focus()}
async function saveDecision(){if(!S.run)throw new Error("실행을 먼저 선택하세요.");const cik=$("#evidence").dataset.cik;await api("/api/decisions",{method:"POST",body:JSON.stringify({cik,state:$("#decision-state").value,rationale:$("#decision-rationale").value,run_id:S.run.run_id,actor:"local-user",evidence_ids:[S.run.run_id]})});S.decisions=await api("/api/decisions");renderRows();renderTimeline();toast("판단 event 추가됨")}
function renderTimeline(){const screens=S.screens||[], runs=S.runs||[], decisions=S.decisions||[];$("#timeline").innerHTML=[...screens.map(x=>`<li>조건 ${esc(x.name)} · revision ${x.revision_number} · ${esc(x.revision_id)}</li>`),...runs.map(x=>`<li>실행 ${esc(x.run_id)} · ${esc(x.fixture_kind)} · ${x.counts.target}개</li>`),...decisions.map(x=>`<li>판단 ${esc(x.cik)} · ${x.before_state||'없음'} → ${x.state} · ${esc(x.rationale)}</li>`)].join('')||'<li>기록 없음</li>'}
async function compareRuns(){const oldId=$("#old-run").value,newId=$("#new-run").value;if(!oldId||!newId)throw new Error("두 실행을 선택하세요.");const diff=await api(`/api/run-comparison?old_run_id=${oldId}&new_run_id=${newId}`);$("#run-diff").textContent=JSON.stringify(diff,null,2)}
async function exportRun(scope,format){if(!S.run)throw new Error("실행이 없습니다.");const selected=scope==="SELECTED"?[...S.selected]:null;if(scope==="SELECTED"&&!selected.length)throw new Error("내보낼 회사를 선택하세요.");const result=await api(`/api/runs/${S.run.run_id}/exports`,{method:"POST",body:JSON.stringify({scope,format,selected_ciks:selected})});toast(`내보내기 완료 · ${result.path}`)}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$("#add-predicate").onclick=()=>predicateRow();$("#saved-screen").onchange=e=>loadScreen(e.target.value);$("#new-screen").onclick=()=>{S.revision=null;$("#saved-screen").value='';$("#screen-name").value='';$("#screen-context").textContent='새 조건';$("#save-state").textContent='저장 대기'};$("#save-screen").onclick=()=>saveScreen().catch(fail);$("#execute").onclick=()=>execute().catch(fail);$("#open-run").onclick=()=>{try{openRun($("#old-run").value)}catch(error){fail(error)}};$("#universe-mode").onchange=e=>$("#universe-values-label").hidden=e.target.value==="ALL_PREPARED";$("#period-mode").onchange=e=>{$("#fiscal-year-label").hidden=e.target.value!=="FIXED_FISCAL_YEAR";$("#offset-label").hidden=e.target.value==="FIXED_FISCAL_YEAR"};$("#show-all").onchange=renderRows;$$('.filters button').forEach(button=>button.onclick=()=>{$$('.filters button').forEach(x=>x.classList.remove('active'));button.classList.add('active');S.activeFilter=button.dataset.filter;renderRows()});$("#close-evidence").onclick=()=>{$("#evidence").hidden=true;S.lastFocus?.focus()};$("#save-decision").onclick=()=>saveDecision().catch(fail);$("#compare-runs").onclick=()=>compareRuns().catch(fail);$("#export-full-csv").onclick=()=>exportRun("FULL","csv").catch(fail);$("#export-full-xlsx").onclick=()=>exportRun("FULL","xlsx").catch(fail);$("#export-selected-csv").onclick=()=>exportRun("SELECTED","csv").catch(fail);$("#export-selected-xlsx").onclick=()=>exportRun("SELECTED","xlsx").catch(fail);'''

JS += r'''
S.dirty=false;S.datasetStatus=[];S.evidenceRow=null;
const DISPLAY_COLUMN_ALIASES={company:["company","ticker","name","cik"],sic:["sic","sic_code","sic_description"],aggregate:["aggregate"],predicates:["predicates"],decision:["decision"]};
function columnEnabled(columns,group){return (DISPLAY_COLUMN_ALIASES[group]||[group]).some(name=>columns.includes(name))}
function predicateRow(value={metric_id:"revenue",operator:"GTE",threshold:"0",definition_version:"annual-core-reported-v1"}){const row=document.createElement("div");row.className="predicate";row.innerHTML=`<label>보고 지표 (USD 원단위)<select class="metric"><option value="revenue">매출</option><option value="cfo">영업활동 현금흐름</option><option value="operating_income">영업이익</option><option value="net_income">순이익</option><option value="revenue_growth" disabled>매출 성장률 · 연간 계산 미지원</option><option value="operating_margin" disabled>영업이익률 · 연간 계산 미지원</option></select></label><label>비교<select class="operator"><option value="GTE">≥ 이상</option><option value="GT">&gt; 초과</option><option value="LTE">≤ 이하</option><option value="LT">&lt; 미만</option><option value="EQ">= 같음</option></select></label><label>기준값 (USD 원단위)<input class="threshold" inputmode="decimal" required></label><button type="button" class="quiet remove" aria-label="조건 삭제">삭제</button>`;row.querySelector(".metric").value=value.metric_id;row.querySelector(".operator").value=value.operator;row.querySelector(".threshold").value=value.threshold;row.querySelector(".remove").onclick=()=>{if($$(".predicate").length>1){row.remove();markDirty()}};$("#predicates").append(row)}
function revisionContent(){const mode=$("#universe-mode").value,values=$("#universe-values").value.split(",").map(v=>v.trim()).filter(Boolean);const universe=mode==="ALL_PREPARED"?{mode}:mode==="SIC"?{mode,sic_codes:values}:{mode,ciks:values};const period=$("#period-mode").value==="FIXED_FISCAL_YEAR"?{mode:"FIXED_FISCAL_YEAR",fiscal_year:Number($("#fiscal-year").value)}:{mode:"LATEST_COMPLETE_ANNUAL",offset:Number($("#period-offset").value)};return {universe,predicates:$$(".predicate").map(row=>({metric_id:row.querySelector(".metric").value,operator:row.querySelector(".operator").value,threshold:row.querySelector(".threshold").value,definition_version:"annual-core-reported-v1"})),period_policy:period,columns:$$('[name="visible-column"]:checked').map(x=>x.value),sort:{column:$("#sort-column").value,direction:$("#sort-direction").value}}}
function markDirty(){if(S.revision){S.dirty=true;$("#save-state").textContent="수정됨 · 새 조건 버전 저장 필요"}else $("#save-state").textContent="저장 대기"}
function isRevisionEdit(target){return target instanceof Element&&!target.closest("#saved-screen,#dataset")}
function trackRevisionEdit(event){if(isRevisionEdit(event.target))markDirty()}
async function boot(){const status=await api("/api/status");S.datasetStatus=status.datasets;$("#dataset").innerHTML=status.datasets.map(d=>`<option value="${esc(d.dataset_id)}">${esc(d.dataset_id)} · ${esc(fixtureLabel(d.fixture_kind))}</option>`).join("");await refreshScreens();await refreshRuns();updateDataset(status.datasets[0]);$("#predicates").innerHTML='';predicateRow();$("#criteria-form").addEventListener("input",trackRevisionEdit);$("#criteria-form").addEventListener("change",trackRevisionEdit)}
async function saveScreen(){$("#criteria-error").hidden=true;$("#save-state").textContent="저장 중…";const content=revisionContent();if(!content.columns.length)throw new Error("표시 열을 하나 이상 선택하세요.");let result;if(S.revision)result=await api(`/api/screens/${S.revision.screen_id}/revisions`,{method:"POST",body:JSON.stringify({content})});else result=await api("/api/screens",{method:"POST",body:JSON.stringify({name:$("#screen-name").value,content})});S.revision=result;S.dirty=false;$("#screen-name").readOnly=true;$("#save-state").textContent=`저장됨 · 조건 버전 ${result.revision_number}`;$("#screen-context").textContent=`${$("#screen-name").value} · v${result.revision_number}`;await refreshScreens();$("#saved-screen").value=result.revision_id;toast("조건 버전 저장 완료")}
function loadScreenRecord(screen){if(!screen)return;S.revision=screen;S.dirty=false;$("#screen-name").value=screen.name;$("#screen-name").readOnly=true;const c=screen.content;$("#universe-mode").value=c.universe.mode;$("#universe-values-label").hidden=c.universe.mode==="ALL_PREPARED";$("#universe-values").value=(c.universe.ciks||c.universe.sic_codes||[]).join(',');$("#period-mode").value=c.period_policy.mode;$("#fiscal-year-label").hidden=c.period_policy.mode!=="FIXED_FISCAL_YEAR";$("#offset-label").hidden=c.period_policy.mode==="FIXED_FISCAL_YEAR";if(c.period_policy.fiscal_year)$("#fiscal-year").value=c.period_policy.fiscal_year;$("#period-offset").value=c.period_policy.offset||0;$("#predicates").innerHTML='';c.predicates.forEach(predicateRow);$("#sort-column").value=c.sort.column;$("#sort-direction").value=c.sort.direction;$$('[name="visible-column"]').forEach(x=>x.checked=columnEnabled(c.columns,x.value));$("#screen-context").textContent=`${screen.name} · v${screen.revision_number}`;$("#save-state").textContent="저장된 조건 버전 열림"}
function loadScreen(id){loadScreenRecord(S.screens.find(x=>x.revision_id===id))}
async function execute(){if(!S.revision)throw new Error("먼저 조건을 저장하세요.");if(S.dirty)throw new Error("화면 조건이 바뀌었습니다. 새 조건 버전을 저장한 뒤 실행하세요.");$("#result-body").innerHTML='<tr><td colspan="6" class="empty">실행 중…</td></tr>';const run=await api("/api/runs",{method:"POST",body:JSON.stringify({revision_id:S.revision.revision_id,dataset_id:$("#dataset").value})});setRun(run);await refreshRuns()}
function setRun(run){S.run=run;S.selected.clear();const d=S.datasetStatus.find(x=>x.dataset_id===run.dataset_id);if(d){$("#dataset").value=d.dataset_id;updateDataset(d)}$("#run-context").textContent=`${run.run_id.slice(-8)} · ${run.fixture_kind}`;$("#period-context").textContent=run.period_policy.mode==="FIXED_FISCAL_YEAR"?`FY${run.period_policy.fiscal_year}`:`최신 완료 FY · ${run.period_policy.offset||0}년 전`;$("#counts").textContent=`대상 ${run.counts.target} · 통과 ${run.counts.pass} · 미충족 ${run.counts.fail} · 미결정 ${run.counts.undetermined} · 품질 차단 ${run.counts.quality_block} (앞 세 상태와 중복 가능)`;$("#provenance").textContent=JSON.stringify({dataset_publication_id:run.dataset_publication_id,versions:run.versions,input_hash:run.input_hash,output_hash:run.output_hash},null,2);renderRows()}
async function openRun(id){if(!id)throw new Error("실행을 선택하세요.");const run=await api(`/api/runs/${id}`),revision=await api(`/api/revisions/${run.revision_id}`);loadScreenRecord(revision);$("#saved-screen").value=revision.revision_id;setRun(run)}
function visible(column){return !S.revision||columnEnabled(S.revision.content.columns,column)}
function renderRows(){if(!S.run)return;$$('[data-column]').forEach(x=>x.hidden=!visible(x.dataset.column));const rows=S.run.rows.filter(r=>S.activeFilter==="ALL"||(S.activeFilter==="BLOCK"?r.quality_blocking:r.aggregate===S.activeFilter)).filter(r=>$("#show-all").checked||r.aggregate==="PASS");$("#result-body").innerHTML=rows.length?rows.map(row=>`<tr data-cik="${row.cik}" class="${S.selected.has(row.cik)?'selected':''}"><td><input type="checkbox" aria-label="${esc(row.ticker)} 선택" ${S.selected.has(row.cik)?'checked':''}></td><td data-column="company" ${visible('company')?'':'hidden'}><button class="quiet company" data-open="${row.cik}"><strong>${esc(row.ticker)} · ${esc(row.name||'이름 미제공')}</strong><small>${row.cik}</small></button></td><td data-column="sic" ${visible('sic')?'':'hidden'}>${esc(row.sic_code||'UNKNOWN_SIC')}<br><small>${esc(row.sic_description||'현재 분류 없음')}</small></td><td data-column="aggregate" ${visible('aggregate')?'':'hidden'}><span class="badge ${row.aggregate.toLowerCase()}">${row.aggregate}</span>${row.quality_blocking?'<br><span class="badge fail">QUALITY BLOCK</span>':''}</td><td data-column="predicates" ${visible('predicates')?'':'hidden'}><div class="pred-list">${row.predicates.map(p=>`<div class="pred-line"><b>${esc(p.metric_id)}</b> ${p.observation&&p.observation.value!==null?esc(p.observation.value)+' USD (원단위)':'—'} · ${p.result}<small>${esc(p.reason)}</small></div>`).join('')}</div></td><td data-column="decision" ${visible('decision')?'':'hidden'}>${decisionFor(row.cik)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">0건 · 상태 필터나 조건을 수정하세요.</td></tr>';$$('[data-cik] input').forEach(el=>el.onchange=()=>{const cik=el.closest('tr').dataset.cik;el.checked?S.selected.add(cik):S.selected.delete(cik);renderRows()});$$('[data-open]').forEach(el=>el.onclick=()=>openEvidence(el.dataset.open,el).catch(fail))}
async function openEvidence(cik,button){S.lastFocus=button;S.evidenceRow=S.run.rows.find(r=>r.cik===cik);$("#evidence-title").textContent=`${S.evidenceRow.ticker} 근거`;$("#evidence-metric").innerHTML=S.evidenceRow.predicates.map(p=>`<option value="${esc(p.metric_id)}">${esc(p.metric_id)}</option>`).join('');const peers=await api(`/api/peers?dataset_id=${encodeURIComponent(S.run.dataset_id)}&cik=${cik}`);$("#peer-company").innerHTML='<option value="">peer 선택</option>'+peers.peers.map(p=>`<option value="${p.cik}" ${p.financial_prepared?'':'disabled'}>${esc((p.tickers||[])[0]||p.name||p.cik)} · ${p.financial_prepared?'재무 준비됨':'metadata만'}</option>`).join('');$("#peer-comparison").textContent=peers.limitation;$("#evidence").dataset.cik=cik;$("#evidence").hidden=false;await renderMetricEvidence();$("#evidence").focus()}
async function renderMetricEvidence(){const metric=$("#evidence-metric").value,row=S.evidenceRow,evaluation=row.predicates.find(p=>p.metric_id===metric),obs=evaluation.observation||{};const series=await api(`/api/series?dataset_id=${encodeURIComponent(S.run.dataset_id)}&cik=${row.cik}&metric_id=${encodeURIComponent(metric)}`);$("#evidence-content").innerHTML=`<dl class="trace-grid"><dt>CIK</dt><dd>${row.cik}</dd><dt>판정</dt><dd>${row.aggregate} · ${esc(evaluation.reason)}</dd><dt>값</dt><dd>${obs.value===null||obs.value===undefined?'—':esc(obs.value)+' USD (원단위)'}</dd><dt>실제 기간</dt><dd>${esc(obs.period_start||'—')} → ${esc(obs.context_end_date||'—')} <small>(source context end, exclusive)</small></dd><dt>단위</dt><dd>${esc(JSON.stringify(obs.unit||null))}</dd><dt>공시</dt><dd>${esc((obs.source_filings||[]).join(', ')||'—')}</dd><dt>Fact</dt><dd>${esc(obs.source_fact_id||'—')}</dd><dt>Mapping</dt><dd>${esc(obs.mapping_relation||'—')}</dd><dt>Quality</dt><dd>${esc(obs.quality_status===null||obs.quality_status===undefined?'NOT_DECLARED':obs.quality_status)}</dd></dl><table class="series-table"><thead><tr><th>FY</th><th>실제 기간</th><th>값</th><th>상태</th></tr></thead><tbody>${series.observations.map(x=>`<tr><td>${x.fiscal_year}</td><td>${esc(x.period_start||'—')} → ${esc(x.context_end_date||'—')}</td><td>${x.value===null?'—':esc(x.value)+' USD'}</td><td>${esc(x.availability_status)} ${esc(x.unavailable_reason||'')}</td></tr>`).join('')}</tbody></table><details><summary>전체 prepared trace</summary><pre>${esc(JSON.stringify(evaluation,null,2))}</pre></details>`}
async function comparePeer(){const peer=$("#peer-company").value;if(!peer)throw new Error("비교할 SIC peer를 선택하세요.");const metric=$("#evidence-metric").value,evaluation=S.evidenceRow.predicates.find(p=>p.metric_id===metric),year=evaluation.observation?.fiscal_year;if(!year)throw new Error("비교 기간이 준비되지 않았습니다.");const result=await api(`/api/peer-comparison?dataset_id=${encodeURIComponent(S.run.dataset_id)}&ciks=${S.evidenceRow.cik},${peer}&metric_id=${encodeURIComponent(metric)}&fiscal_year=${year}`);$("#peer-comparison").innerHTML=`<p>${esc(result.warning)}</p><table class="series-table"><thead><tr><th>회사</th><th>실제 기간</th><th>값</th><th>Mapping</th></tr></thead><tbody>${result.rows.map(x=>`<tr><td>${esc(x.company.ticker)}</td><td>${esc(x.observation?.period_start||'—')} → ${esc(x.observation?.context_end_date||'—')}</td><td>${x.observation?.value===null||x.observation?.value===undefined?'—':esc(x.observation.value)+' USD'}</td><td>${esc(x.observation?.mapping_relation||'—')}</td></tr>`).join('')}</tbody></table>`}
async function searchMetadata(event){event.preventDefault();const q=new URLSearchParams({dataset_id:$("#dataset").value,limit:"100"});if($("#metadata-query").value)q.set("query",$("#metadata-query").value);if($("#metadata-sic").value)q.set("sic_code",$("#metadata-sic").value);if($("#metadata-prepared").value)q.set("prepared",$("#metadata-prepared").value);const result=await api(`/api/metadata?${q}`);$("#metadata-results").innerHTML=`${result.total}건 중 ${result.rows.length}건 표시<ul>${result.rows.map(x=>`<li><b>${esc((x.tickers||[])[0]||x.name||x.cik)}</b> · ${x.cik} · ${esc(x.sic_code||'UNKNOWN_SIC')} · ${x.financial_prepared?'재무 준비됨':'metadata만'}</li>`).join('')}</ul>`}
async function exportRun(scope,format){if(!S.run)throw new Error("실행이 없습니다.");const selected=scope==="SELECTED"?[...S.selected]:null;if(scope==="SELECTED"&&!selected.length)throw new Error("내보낼 회사를 선택하세요.");const result=await api(`/api/runs/${S.run.run_id}/exports`,{method:"POST",body:JSON.stringify({scope,format,selected_ciks:selected})});const link=document.createElement('a');link.href=result.download_url;link.download='';document.body.append(link);link.click();link.remove();toast(`${scope==='FULL'?'전체':'선택'} ${format.toUpperCase()} 다운로드 시작`)}
$("#saved-screen").onchange=e=>loadScreen(e.target.value);$("#new-screen").onclick=()=>{S.revision=null;S.dirty=false;$("#saved-screen").value='';$("#screen-name").readOnly=false;$("#screen-name").value='';$("#screen-context").textContent='새 조건';$("#save-state").textContent='저장 대기'};$("#add-predicate").onclick=()=>{predicateRow();markDirty()};$("#save-screen").onclick=()=>saveScreen().catch(fail);$("#execute").onclick=()=>execute().catch(fail);$("#open-run").onclick=()=>openRun($("#old-run").value).catch(fail);$("#metadata-form").onsubmit=e=>searchMetadata(e).catch(fail);$("#evidence-metric").onchange=()=>renderMetricEvidence().catch(fail);$("#compare-peer").onclick=()=>comparePeer().catch(fail);$("#export-full-csv").onclick=()=>exportRun("FULL","csv").catch(fail);$("#export-full-xlsx").onclick=()=>exportRun("FULL","xlsx").catch(fail);$("#export-selected-csv").onclick=()=>exportRun("SELECTED","csv").catch(fail);$("#export-selected-xlsx").onclick=()=>exportRun("SELECTED","xlsx").catch(fail);
$("#evidence").addEventListener("keydown",event=>{if(event.key==="Escape"){$("#close-evidence").click();return}if(event.key!=="Tab")return;const focusable=$$("#evidence button:not([disabled]),#evidence select:not([disabled]),#evidence textarea:not([disabled]),#evidence summary");if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
api("/api/decisions").then(x=>{S.decisions=x;renderTimeline()}).then(boot).catch(fail);

// Final interaction layer: paging, human-readable comparison, canonical trace, and stable save/focus state.
S.metadataOffset=0;S.metadataLimit=50;S.metadataTotal=0;
function metricLabel(id){return ({revenue:"매출",cfo:"영업활동 현금흐름",operating_income:"영업이익",net_income:"순이익"})[id]||id}
function reasonText(code){return ({PREDICATE_MATCHED:"조건을 충족했습니다.",PREDICATE_NOT_MATCHED:"조건을 충족하지 않았습니다.",MULTIPLE_CANDIDATES:"같은 기간에 후보 값이 여러 개라 자동 선택하지 않았습니다.",PERIOD_NOT_PREPARED:"이 기간의 보고 값이 준비되지 않았습니다.",QUALITY_BLOCKED:"자료 품질 조건 때문에 판정을 보류했습니다."})[code]||"상세 사유를 확인하세요."}
function renderRows(){if(!S.run)return;$$('[data-column]').forEach(x=>x.hidden=!visible(x.dataset.column));const rows=S.run.rows.filter(r=>S.activeFilter==="ALL"||(S.activeFilter==="BLOCK"?r.quality_blocking:r.aggregate===S.activeFilter)).filter(r=>$("#show-all").checked||r.aggregate==="PASS");$("#result-body").innerHTML=rows.length?rows.map(row=>`<tr data-cik="${row.cik}" class="${S.selected.has(row.cik)?'selected':''}"><td><input type="checkbox" aria-label="${esc(row.ticker)} 선택" ${S.selected.has(row.cik)?'checked':''}></td><td data-column="company" ${visible('company')?'':'hidden'}><button class="company" data-open="${row.cik}"><strong>${esc(row.ticker)} · ${esc(row.name||'이름 미제공')}</strong><small>${row.cik}</small></button></td><td data-column="sic" ${visible('sic')?'':'hidden'}>${esc(row.sic_code||'UNKNOWN_SIC')}<br><small>${esc(row.sic_description||'현재 분류 없음')}</small></td><td data-column="aggregate" ${visible('aggregate')?'':'hidden'}><span class="badge ${row.aggregate.toLowerCase()}">${row.aggregate}</span>${row.quality_blocking?'<br><span class="badge fail">QUALITY BLOCK</span>':''}</td><td data-column="predicates" ${visible('predicates')?'':'hidden'}><div class="pred-list">${row.predicates.map(p=>`<div class="pred-line"><b>${esc(metricLabel(p.metric_id))}</b> ${p.observation&&p.observation.value!==null?esc(p.observation.value)+' USD 원단위':'—'} · ${p.result}<small>${esc(reasonText(p.reason))}</small><details class="reason"><summary>기술 사유</summary><code>${esc(p.reason)}</code></details></div>`).join('')}</div></td><td data-column="decision" ${visible('decision')?'':'hidden'}>${decisionFor(row.cik)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">0건 · 상태 필터나 조건을 수정하세요.</td></tr>';$$('[data-cik] input').forEach(el=>el.onchange=()=>{const cik=el.closest('tr').dataset.cik;el.checked?S.selected.add(cik):S.selected.delete(cik);renderRows()});$$('[data-open]').forEach(el=>el.onclick=()=>openEvidence(el.dataset.open,el).catch(fail))}
function fail(error){$("#criteria-error").hidden=false;$("#criteria-error").textContent=error.message||String(error);$("#review-context").textContent="작업 오류 · 상세 확인"}
function saveFail(error){fail(error);$("#save-state").textContent=S.dirty?"수정됨 · 저장 실패":S.revision?`저장됨 · 조건 버전 ${S.revision.revision_number}`:"저장 실패 · 저장되지 않음"}
async function renderMetricEvidence(){const metric=$("#evidence-metric").value,row=S.evidenceRow,evaluation=row.predicates.find(p=>p.metric_id===metric),obs=evaluation.observation||{};$("#evidence-content").innerHTML='<p class="loading">근거와 연간 기록을 불러오는 중…</p>';const [series,trace]=await Promise.all([api(`/api/series?dataset_id=${encodeURIComponent(S.run.dataset_id)}&cik=${row.cik}&metric_id=${encodeURIComponent(metric)}`),api(`/api/runs/${encodeURIComponent(S.run.run_id)}/trace?cik=${row.cik}&metric_id=${encodeURIComponent(metric)}`)]);$("#evidence-content").innerHTML=`<dl class="trace-grid"><dt>CIK</dt><dd>${row.cik}</dd><dt>판정</dt><dd>${row.aggregate} · ${esc(evaluation.reason)}</dd><dt>값</dt><dd>${obs.value===null||obs.value===undefined?'—':esc(obs.value)+' USD 원단위'}</dd><dt>실제 기간</dt><dd>${esc(obs.period_start||'—')} → ${esc(obs.context_end_date||'—')} <small>(원천 context end · exclusive)</small></dd><dt>단위</dt><dd>${esc(JSON.stringify(obs.unit||null))}</dd><dt>공시 accession</dt><dd>${esc((obs.source_filings||[]).join(', ')||'—')}</dd><dt>Raw Fact</dt><dd>${esc(obs.source_fact_id||'—')}</dd><dt>Mapping 관계</dt><dd>${esc(obs.mapping_relation||'—')}</dd><dt>Quality 상태</dt><dd>${esc(obs.quality_status===null||obs.quality_status===undefined?'NOT_DECLARED':obs.quality_status)}</dd></dl><h3>${esc(metricLabel(metric))} · 보고된 연간 원값</h3><table class="series-table"><thead><tr><th>FY</th><th>실제 기간</th><th>USD 원값</th><th>상태</th></tr></thead><tbody>${series.observations.map(x=>`<tr><td>${x.fiscal_year}</td><td>${esc(x.period_start||'—')} → ${esc(x.context_end_date||'—')}</td><td>${x.value===null?'—':esc(x.value)}</td><td>${esc(x.availability_status)} ${esc(x.unavailable_reason||'')}</td></tr>`).join('')}</tbody></table><details><summary>기술 근거 전체 보기</summary><pre>${esc(JSON.stringify(trace,null,2))}</pre></details>`}
async function searchMetadata(event,offset=0){event?.preventDefault();S.metadataOffset=Math.max(0,offset);const q=new URLSearchParams({dataset_id:$("#dataset").value,limit:String(S.metadataLimit),offset:String(S.metadataOffset)});if($("#metadata-query").value)q.set("query",$("#metadata-query").value);if($("#metadata-sic").value)q.set("sic_code",$("#metadata-sic").value);if($("#metadata-prepared").value)q.set("prepared",$("#metadata-prepared").value);$("#metadata-results").innerHTML='<span class="loading">회사 목록을 불러오는 중…</span>';const result=await api(`/api/metadata?${q}`);S.metadataTotal=result.total;const first=result.total?result.offset+1:0,last=result.offset+result.rows.length;$("#metadata-results").innerHTML=result.rows.length?`<ul>${result.rows.map(x=>`<li><b>${esc((x.tickers||[])[0]||x.name||x.cik)}</b> · <span class="technical">${x.cik}</span> · ${esc(x.sic_code||'UNKNOWN_SIC')} · ${x.financial_prepared?'재무 준비됨':'NOT_PREPARED · metadata만'}</li>`).join('')}</ul>`:'검색 결과가 없습니다.';$("#metadata-page").textContent=`${first}–${last} / ${result.total}`;$("#metadata-prev").disabled=result.offset===0;$("#metadata-next").disabled=last>=result.total}
function renderTimeline(){const screens=S.screens||[],runs=S.runs||[],decisions=S.decisions||[];$("#timeline").innerHTML=[...screens.map(x=>`<li><b>조건 버전</b> ${esc(x.name)} · v${x.revision_number}<div class="timeline-meta">${esc(x.created_at||'')} · ${esc(x.revision_id)}</div></li>`),...runs.map(x=>`<li><b>실행</b> ${esc(x.run_id.slice(-8))} · ${esc(x.fixture_kind)} · 대상 ${x.counts.target}개<div class="timeline-meta">${esc(x.created_at||'')} · 결과 hash ${esc(x.output_hash||'—')}</div></li>`),...decisions.map(x=>`<li class="decision"><b>판단 기록</b> ${esc(x.cik)} · ${esc(x.before_state||'없음')} → ${esc(x.state)}<div>${esc(x.rationale)}</div><div class="timeline-meta">${esc(x.actor)} · ${esc(x.created_at)} · 실행 ${esc(x.run_id.slice(-8))}</div></li>`)].join('')||'<li>기록 없음</li>'}
async function compareRuns(){const oldId=$("#old-run").value,newId=$("#new-run").value;if(!oldId||!newId)throw new Error("두 실행을 선택하세요.");$("#run-diff").innerHTML='<span class="loading">두 실행을 비교하는 중…</span>';const d=await api(`/api/run-comparison?old_run_id=${encodeURIComponent(oldId)}&new_run_id=${encodeURIComponent(newId)}`),labels={data:"자료출처·버전",rule:"계산 규칙",universe:"회사 구성",universe_selector:"Universe 조건",condition_revision:"조건 버전",manual_decision:"사용자 판단 기록"},changed=Object.entries(d.changed_dimensions).filter(([,v])=>v).map(([k])=>labels[k]||k);$("#run-diff").classList.remove("empty-diff");$("#run-diff").innerHTML=`<div class="diff-summary"><div><strong>변경 구분</strong>${esc(changed.join(', ')||'변경 없음')}</div><div><strong>결과가 다른 회사</strong>${d.differences.length}개</div><div><strong>자료 성격</strong>${d.fixture_kinds.map(esc).join(' → ')}</div></div><p>${d.attribution==='NO_VERSION_CHANGE'?'자료·규칙·Universe 버전 변경이 없습니다.':d.attribution==='MIXED_OR_INCOMPARABLE_VERSION_CHANGE'?'여러 변경이 함께 있어 단일 원인으로 단정할 수 없습니다.':'한 변경 차원이 감지됐습니다.'}</p><details><summary>기술 차이 · version/hash JSON</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details>`}
$("#save-screen").onclick=()=>saveScreen().catch(saveFail);$("#metadata-form").onsubmit=e=>searchMetadata(e,0).catch(fail);$("#metadata-prev").onclick=()=>searchMetadata(null,S.metadataOffset-S.metadataLimit).catch(fail);$("#metadata-next").onclick=()=>searchMetadata(null,S.metadataOffset+S.metadataLimit).catch(fail);$("#close-evidence").onclick=()=>{const cik=$("#evidence").dataset.cik;$("#evidence").hidden=true;($(`[data-open="${cik}"]`)||S.lastFocus)?.focus()};

function aggregateLabel(value){return ({PASS:"통과",FAIL:"미충족",UNDETERMINED:"미결정"})[value]||value}
function decisionLabel(value){return ({INTEREST:"관심",HOLD:"보류",EXCLUDE:"제외"})[value]||value||"없음"}
function availabilityLabel(value){return ({AVAILABLE:"사용 가능",UNAVAILABLE:"사용 불가",REVIEW_REQUIRED:"검토 필요",QUALITY_BLOCKED:"품질 차단"})[value]||value}
function fixtureLabel(value){return value==="ACTUAL_PREPARED"?"실제 준비 자료":"검증용 자료"}
function formatUsd(value){if(value===null||value===undefined)return "—";const raw=String(value);if(!/^-?\d+(?:\.\d+)?$/.test(raw))return raw;const [integer,fraction]=raw.split(".");const sign=integer.startsWith("-")?"-":"",digits=sign?integer.slice(1):integer;return sign+digits.replace(/\B(?=(\d{3})+(?!\d))/g,",")+(fraction===undefined?"":"."+fraction)}
function setCriteriaCompact(compact){const section=$(".criteria"),button=$("#toggle-criteria");section.classList.toggle("compact",compact);button.setAttribute("aria-expanded",String(!compact));button.textContent=compact?"조건 펼치기":"조건 접기"}
function decisionFor(cik){const events=(S.decisions||[]).filter(e=>e.cik===cik);return events.length?`<span class="badge review">${esc(decisionLabel(events.at(-1).state))}</span>`:'<span class="muted">기록 없음</span>'}
function renderRows(){if(!S.run)return;$$('[data-column]').forEach(x=>x.hidden=!visible(x.dataset.column));const rows=S.run.rows.filter(r=>S.activeFilter==="ALL"||(S.activeFilter==="BLOCK"?r.quality_blocking:r.aggregate===S.activeFilter)).filter(r=>$("#show-all").checked||r.aggregate==="PASS");$("#result-body").innerHTML=rows.length?rows.map(row=>`<tr data-cik="${row.cik}" class="${S.selected.has(row.cik)?'selected':''}"><td><input type="checkbox" aria-label="${esc(row.ticker)} 선택" ${S.selected.has(row.cik)?'checked':''}></td><td data-column="company" ${visible('company')?'':'hidden'}><button class="company" data-open="${row.cik}"><strong>${esc(row.ticker)} · ${esc(row.name||'이름 미제공')}</strong><small>${row.cik}</small></button></td><td data-column="sic" ${visible('sic')?'':'hidden'}>${esc(row.sic_code||'UNKNOWN_SIC')}<br><small>${esc(row.sic_description||'현재 분류 없음')}</small></td><td data-column="aggregate" ${visible('aggregate')?'':'hidden'}><span class="badge ${row.aggregate.toLowerCase()}">${esc(aggregateLabel(row.aggregate))}</span>${row.quality_blocking?'<br><span class="badge fail">품질 차단</span>':''}</td><td data-column="predicates" ${visible('predicates')?'':'hidden'}><div class="pred-list">${row.predicates.map(p=>{const raw=p.observation?.value;return `<div class="pred-line"><b>${esc(metricLabel(p.metric_id))}</b> ${raw===null||raw===undefined?'—':esc(formatUsd(raw))+' USD'} · <span class="state-label">${esc(aggregateLabel(p.result))}</span><small>${esc(reasonText(p.reason))}</small><details class="reason"><summary>정확한 값·기술 사유</summary><div class="exact-value">${raw===null||raw===undefined?'값 없음':esc(String(raw))+' USD (canonical 원문)'}</div><code>metric=${esc(p.metric_id)} · result=${esc(p.result)} · reason=${esc(p.reason)}</code></details></div>`}).join('')}</div></td><td data-column="decision" ${visible('decision')?'':'hidden'}>${decisionFor(row.cik)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">0건 · 상태 필터나 조건을 수정하세요.</td></tr>';$$('[data-cik] input').forEach(el=>el.onchange=()=>{const cik=el.closest('tr').dataset.cik;el.checked?S.selected.add(cik):S.selected.delete(cik);renderRows()});$$('[data-open]').forEach(el=>el.onclick=()=>openEvidence(el.dataset.open,el).catch(fail))}
function renderTimeline(){const screens=S.screens||[],runs=S.runs||[],decisions=S.decisions||[];$("#timeline").innerHTML=[...screens.map(x=>`<li><div class="timeline-primary"><b>조건 저장 · ${esc(x.name)} v${x.revision_number}</b><time>${esc(x.created_at||'')}</time></div><details class="timeline-technical"><summary>조건 버전 ID</summary><pre>${esc(x.revision_id)}</pre></details></li>`),...runs.map(x=>`<li><div class="timeline-primary"><b>실행 · ${fixtureLabel(x.fixture_kind)} · 대상 ${x.counts.target}개</b><time>${esc(x.created_at||'')}</time></div><div class="timeline-meta">통과 ${x.counts.pass} · 미충족 ${x.counts.fail} · 미결정 ${x.counts.undetermined}</div><details class="timeline-technical"><summary>실행 ID·자료 enum·결과 hash</summary><pre>run_id=${esc(x.run_id)}\nfixture_kind=${esc(x.fixture_kind)}\noutput_hash=${esc(x.output_hash||'—')}</pre></details></li>`),...decisions.map(x=>`<li class="decision"><div class="timeline-primary"><b>판단 기록 · ${esc(x.cik)} · ${esc(decisionLabel(x.before_state))} → ${esc(decisionLabel(x.state))}</b><time>${esc(x.created_at)}</time></div><div>${esc(x.rationale)}</div><div class="timeline-meta">작성자 ${esc(x.actor)}</div><details class="timeline-technical"><summary>판단·실행 식별자</summary><pre>state=${esc(x.state)}\nrun_id=${esc(x.run_id)}\nevent_id=${esc(x.event_id||'—')}</pre></details></li>`)].join('')||'<li>기록 없음</li>'}
const originalSetRun=setRun;setRun=function(run){originalSetRun(run);$("#run-context").textContent=`${run.run_id.slice(-8)} · ${fixtureLabel(run.fixture_kind)}`;setCriteriaCompact(true)};
$("#toggle-criteria").onclick=()=>setCriteriaCompact(!$(".criteria").classList.contains("compact"));
const originalNewScreen=$("#new-screen").onclick;$("#new-screen").onclick=()=>{originalNewScreen();setCriteriaCompact(false);$("#screen-name").focus()};
'''
